/**
 * Security Tests - JWT Algorithm and token-type Validation
 * Verifies RBAC middleware rejects HS256/default-secret and non-access tokens.
 *
 * Test keys are generated by CI before the test suite; no private key is
 * committed to the repository.
 */
const jwt = require('jsonwebtoken');
const fs = require('fs');
const path = require('path');
const { authenticate } = require('../../presentation/middleware/rbac.middleware');

const PRIVATE_KEY_PATH = path.resolve(__dirname, '../../../00-infrastructure/keys/jwt_private.pem');
const PRIVATE_KEY = fs.readFileSync(PRIVATE_KEY_PATH, 'utf8');

function mockReq(token) {
  return { headers: { authorization: token ? `Bearer ${token}` : undefined, cookie: undefined }, query: {}, body: {} };
}
function mockRes() {
  let code = 200, body = null;
  return { status(c) { code = c; return this; }, json(o) { body = o; return this; }, getCode: () => code };
}
function mockNext() { let called = false; return { call: () => { called = true; }, wasCalled: () => called }; }

function issueAccessToken(payload = {}) {
  return jwt.sign({ ...payload, type: 'access' }, PRIVATE_KEY, { algorithm: 'RS256', expiresIn: '1h' });
}

describe('JWT Algorithm and Token-Type Security', () => {
  test('Valid RS256 access token is accepted', () => {
    const token = issueAccessToken({ userId: 'u1', role: 'admin' });
    const req = mockReq(token), res = mockRes(), next = mockNext();
    authenticate(req, res, next.call);
    expect(next.wasCalled()).toBe(true);
    expect(req.user.role).toBe('admin');
    expect(req.user.type).toBe('access');
  });

  test('RS256 token without access type is REJECTED', () => {
    const token = jwt.sign({ userId: 'u1', role: 'admin' }, PRIVATE_KEY, { algorithm: 'RS256', expiresIn: '1h' });
    const req = mockReq(token), res = mockRes(), next = mockNext();
    authenticate(req, res, next.call);
    expect(next.wasCalled()).toBe(false);
    expect(res.getCode()).toBe(401);
  });

  test('RS256 refresh-type token is REJECTED', () => {
    const token = jwt.sign({ userId: 'u1', role: 'admin', type: 'refresh' }, PRIVATE_KEY, { algorithm: 'RS256', expiresIn: '1h' });
    const req = mockReq(token), res = mockRes(), next = mockNext();
    authenticate(req, res, next.call);
    expect(next.wasCalled()).toBe(false);
    expect(res.getCode()).toBe(401);
  });

  test('HS256 token with default secret is REJECTED', () => {
    const token = jwt.sign({ userId: 'u1', role: 'admin', type: 'access' }, 'safara_dev_secret', { algorithm: 'HS256', expiresIn: '1h' });
    const req = mockReq(token), res = mockRes(), next = mockNext();
    authenticate(req, res, next.call);
    expect(next.wasCalled()).toBe(false);
    expect(res.getCode()).toBe(401);
  });

  test('HS256 token with random secret is REJECTED', () => {
    const token = jwt.sign({ userId: 'u1', role: 'super_admin', type: 'access' }, 'random_secret', { algorithm: 'HS256', expiresIn: '1h' });
    const req = mockReq(token), res = mockRes(), next = mockNext();
    authenticate(req, res, next.call);
    expect(next.wasCalled()).toBe(false);
    expect(res.getCode()).toBe(401);
  });

  test('No token is REJECTED', () => {
    const req = mockReq(null), res = mockRes(), next = mockNext();
    authenticate(req, res, next.call);
    expect(next.wasCalled()).toBe(false);
    expect(res.getCode()).toBe(401);
  });

  test('Malformed token is REJECTED', () => {
    const req = mockReq('bad.token.here'), res = mockRes(), next = mockNext();
    authenticate(req, res, next.call);
    expect(next.wasCalled()).toBe(false);
    expect(res.getCode()).toBe(401);
  });
});
